    SELECT @t, 'HM65-03', N'Smoking Repassage', @c, 4000, @taux, 0, 0, 1, N'Pièce', (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65'), 0, -3000, N'Repassage', 0 WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM65-03');
UPDATE Produits SET Nom = N'Smoking Repassage', CategorieId = @c, PrixVente = 4000, Supplement = -3000, LibelleVariante = N'Repassage' WHERE TenantId = @t AND Code = 'HM65-03';
INSERT INTO VarianteValeurs (VarianteId, ValeurId) SELECT v.Id, (SELECT MIN(Id) FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65') AND Nom = N'Prestation') AND Valeur = N'Repassage')
    FROM Produits v WHERE v.TenantId = @t AND v.Code = 'HM65-03' AND NOT EXISTS (SELECT 1 FROM VarianteValeurs x WHERE x.VarianteId = v.Id);
INSERT INTO ProduitAttributValeurs (ProduitAttributId, Valeur, Ordre) SELECT (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65') AND Nom = N'Prestation'), N'Enfants', 3 WHERE NOT EXISTS (SELECT 1 FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65') AND Nom = N'Prestation') AND Valeur = N'Enfants');
INSERT INTO Produits (TenantId, Code, Nom, CategorieId, PrixVente, TauxTVA, SuiviStock, StockActuel, Actif, Unite, ParentId, EstModele, Supplement, LibelleVariante, EstCombo)
    SELECT @t, 'HM65-04', N'Smoking Enfants', @c, 3000, @taux, 0, 0, 1, N'Pièce', (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65'), 0, -4000, N'Enfants', 0 WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM65-04');
UPDATE Produits SET Nom = N'Smoking Enfants', CategorieId = @c, PrixVente = 3000, Supplement = -4000, LibelleVariante = N'Enfants' WHERE TenantId = @t AND Code = 'HM65-04';
INSERT INTO VarianteValeurs (VarianteId, ValeurId) SELECT v.Id, (SELECT MIN(Id) FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM65') AND Nom = N'Prestation') AND Valeur = N'Enfants')
    FROM Produits v WHERE v.TenantId = @t AND v.Code = 'HM65-04' AND NOT EXISTS (SELECT 1 FROM VarianteValeurs x WHERE x.VarianteId = v.Id);

-- Catégories de la première version du catalogue, devenues vides
DELETE FROM Categories WHERE TenantId = @t AND Nom IN (N'Chemises et hauts', N'Vestes et blousons', N'Bas', N'Tenues et costumes', N'Linge de maison', N'Accessoires et sous-vêtements') AND NOT EXISTS (SELECT 1 FROM Produits p WHERE p.CategorieId = Categories.Id);

-- TVA de la société (si elle existe) sur les modèles et leurs variantes
INSERT INTO ProduitTaxes (ProduitId, TaxeId) SELECT p.Id, @tva FROM Produits p WHERE p.TenantId = @t AND @tva IS NOT NULL
    AND (p.Code IN ('HM08', 'HM09', 'HM10', 'HM22', 'HM28', 'HM29', 'HM30', 'HM42', 'HM35', 'HM36', 'HM37', 'HM38', 'HM54', 'HM58', 'HM59', 'HM60', 'HM06', 'HM07', 'HM11', 'HM12', 'HM13', 'HM14', 'HM15', 'HM17', 'HM43', 'HM34', 'HM32', 'HM39', 'HM48', 'HM49', 'HM50', 'HM79', 'HM81', 'HM82', 'HM83', 'HM05', 'HM75', 'HM76', 'HM77', 'HM20', 'HM21', 'HM23', 'HM33', 'HM68', 'HM18', 'HM19', 'HM31', 'HM27', 'HM69', 'HM70', 'HM71', 'HM72', 'HM73', 'HM02', 'HM03', 'HM04', 'HM47', 'HM78', 'HM52', 'HM53', 'HM84', 'HM44', 'HM51', 'HM66', 'HM80', 'HM55', 'HM56', 'HM57', 'HM40', 'HM41', 'HM61', 'HM62', 'HM63', 'HM16', 'HM24', 'HM25', 'HM26', 'HM45', 'HM46', 'HM74', 'HM01', 'HM64', 'HM65') OR p.ParentId IN (SELECT Id FROM Produits WHERE TenantId = @t AND Code IN ('HM08', 'HM09', 'HM10', 'HM22', 'HM28', 'HM29', 'HM30', 'HM42', 'HM35', 'HM36', 'HM37', 'HM38', 'HM54', 'HM58', 'HM59', 'HM60', 'HM06', 'HM07', 'HM11', 'HM12', 'HM13', 'HM14', 'HM15', 'HM17', 'HM43', 'HM34', 'HM32', 'HM39', 'HM48', 'HM49', 'HM50', 'HM79', 'HM81', 'HM82', 'HM83', 'HM05', 'HM75', 'HM76', 'HM77', 'HM20', 'HM21', 'HM23', 'HM33', 'HM68', 'HM18', 'HM19', 'HM31', 'HM27', 'HM69', 'HM70', 'HM71', 'HM72', 'HM73', 'HM02', 'HM03', 'HM04', 'HM47', 'HM78', 'HM52', 'HM53', 'HM84', 'HM44', 'HM51', 'HM66', 'HM80', 'HM55', 'HM56', 'HM57', 'HM40', 'HM41', 'HM61', 'HM62', 'HM63', 'HM16', 'HM24', 'HM25', 'HM26', 'HM45', 'HM46', 'HM74', 'HM01', 'HM64', 'HM65')))
    AND NOT EXISTS (SELECT 1 FROM ProduitTaxes x WHERE x.ProduitId = p.Id);
COMMIT TRANSACTION;
SELECT N'Catalogue Hob''s-Marie installé : ' + CAST((SELECT COUNT(*) FROM Produits WHERE TenantId = @t AND Code LIKE 'HM%' AND ParentId IS NULL) AS nvarchar(10))
    + N' articles, ' + CAST((SELECT COUNT(*) FROM Produits WHERE TenantId = @t AND Code LIKE 'HM%-0_') AS nvarchar(10)) + N' variantes.' AS Resultat;
END
